import sys, json
def solve(grid):
    if not grid or grid[0][0] == 1: return 0
    m, n = len(grid), len(grid[0])
    dp = [0]*n; dp[0] = 1
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1: dp[c] = 0
            elif c > 0: dp[c] += dp[c-1]
    return dp[n-1]
if __name__ == '__main__':
    content = sys.stdin.read().strip()
    if content:
        grid = json.loads(content)
        print(solve(grid))

