using namespace std;
int main() {
    string s, line; while(getline(cin, line)) s += line;
    if (s.empty()) return 0;
    // Simple parser
    vector<vector<int>> g;
    size_t i = 0;
    while(i < s.length()){
        if(s[i] == '['){
            size_t j = i + 1;
            while(j < s.length() && s[j] != '['){ if(s[j] == ']') break; j++; }
            if(j < s.length() && s[j] == '['){
                size_t k = j + 1; while(k < s.length() && s[k] != ']') k++;
                string r = s.substr(j+1, k-j-1); for(char &c : r) if(c == ',') c = ' ';
                stringstream ss(r); int v; vector<int> row; while(ss >> v) row.push_back(v);
                if(!row.empty() || r.find('0') != string::npos) g.push_back(row);
                i = k + 1;
            } else i++;
        } else i++;
    }
    if(g.empty() || g[0][0] == 1){ cout << 0 << endl; return 0; }
    int n = g[0].size(); vector<long long> dp(n, 0); dp[0] = 1;
    for(auto& r : g){ for(int c=0; c<n; c++){ if(r[c] == 1) dp[c] = 0; else if(c > 0) dp[c] += dp[c-1]; } }
    cout << dp[n-1] << endl;
    return 0;
}

