        String s = sb.toString().trim(); if(s.isEmpty()) return;
        List<int[]> list = new ArrayList<>();
        int i = 0;
        while(i < s.length()){
            if(s.charAt(i) == '['){
                int j = i + 1; while(j < s.length() && s.charAt(j) != '['){ if(s.charAt(j) == ']') break; j++; }
                if(j < s.length() && s.charAt(j) == '['){
                    int k = j + 1; while(k < s.length() && s.charAt(k) != ']') k++;
                    String r = s.substring(j+1, k).replace(",", " ").trim();
                    if(!r.isEmpty()){
                        String[] p = r.split("\\s+"); int[] row = new int[p.length];
                        for(int x=0; x<p.length; x++) row[x] = Integer.parseInt(p[x]);
                        list.add(row);
                    } else if(s.substring(j, k+1).equals("[]")) list.add(new int[0]);
                    i = k + 1;
                } else if(s.charAt(i+1) == '0' || s.charAt(i+1) == '1'){
                    list.add(new int[]{s.charAt(i+1) - '0'}); break;
                } else i++;
            } else i++;
        }
        int[][] g = list.toArray(new int[0][]);
        if(g.length == 0 || g[0].length == 0 || g[0][0] == 1){ System.out.println(0); return; }
        int n = g[0].length; long[] dp = new long[n]; dp[0] = 1;
        for(int[] r : g){ for(int c=0; c<n; c++){ if(r[c] == 1) dp[c] = 0; else if(c > 0) dp[c] += dp[c-1]; } }
        System.out.println(dp[n-1]);
    }
}

